{
  "steps": [
    {
      "id": "street_names",
      "operation": "run_sql",
      "arguments": {
        "query": "SELECT name FROM read_parquet('input_1')",
        "output_path": "street_names.parquet",
        "input_paths": ["input_1"]
      },
      "comment": "list street names from streets table (input_1)",
      "output": {"kind": "table", "geometry": "optional", "cardinality": "same_as_input"}
    },
    {
      "id": "all_streets",
      "operation": "run_sql",
      "arguments": {
        "query": "SELECT * FROM read_parquet('input_1')",
        "output_path": "all_streets.parquet",
        "input_paths": ["input_1"]
      },
      "comment": "show every street record from streets table (input_1), no filtering",
      "output": {"kind": "table", "geometry": "optional", "cardinality": "same_as_input"}
    },
    {
      "id": "main_road",
      "operation": "select_features",
      "arguments": {
        "input_path": "input_1",
        "output_path": "main_road.parquet",
        "by": "field_equals",
        "field": "name",
        "value": "Main Road"
      },
      "comment": "show only the record for Main Road from streets table (input_1)",
      "output": {"kind": "vector", "geometry": "line", "cardinality": "one"}
    }
  ],
  "assumptions": [
    "streets_table=input_1 is the sole source for all three requested views",
    "name_field=name holds the street name attribute used for both listing names and filtering Main Road",
    "main_road_match=exact equality on name field value 'Main Road'",
    "streets_geometry=line (streets are typically represented as line features, though source is described as a table)",
    "main_road_cardinality=exactly one record matches 'Main Road'"
  ],
  "warnings": [
    "select_features always outputs a vector dataset per its contract, even though the source is described as a table layer; this is not a relabeling error but the operation's declared guarantee.",
    "If 'Main Road' corresponds to multiple segments/records, the select_features output would contain more than one row; cardinality is assumed to be exactly one based on the singular phrasing 'the record'."
  ]
}

