{
  "steps": [
    {
      "id": "make_point",
      "operation": "run_sql",
      "arguments": {
        "query": "SELECT ST_Point(1, 1) AS geom",
        "output_path": "point.parquet",
        "input_paths": []
      },
      "output": {"kind": "vector", "geometry": "point", "cardinality": "one"}
    },
    {
      "id": "point_as_text",
      "operation": "run_sql",
      "arguments": {
        "query": "SELECT ST_AsText(geom) AS wkt FROM read_parquet('$make_point')",
        "output_path": "point_text.parquet",
        "input_paths": ["$make_point"]
      },
      "comment": "Reads the point geometry back as human-readable WKT text",
      "output": {"kind": "table", "cardinality": "one"}
    },
    {
      "id": "buffer_area",
      "operation": "run_sql",
      "arguments": {
        "query": "SELECT ST_Buffer(geom, 1) AS geom FROM read_parquet('$make_point')",
        "output_path": "buffer_area.parquet",
        "input_paths": ["$make_point"]
      },
      "comment": "Computes the polygon area within 1 coordinate unit of the point",
      "output": {"kind": "vector", "geometry": "polygon", "cardinality": "one"}
    }
  ],
  "assumptions": [
    "crs=none declared; point treated as a planar coordinate pair",
    "unit=1 literal coordinate unit (not reprojected to meters), so buffer_layer's metric/UTM buffering is not used",
    "no_input_dataset=the point is constructed purely from the literal coordinates (1,1) via run_sql"
  ],
  "warnings": [
    "Because no CRS is specified for the (1,1) coordinate, the buffer radius of 1 is applied directly in the same (unspecified) coordinate units rather than being converted to a ground distance in meters."
  ]
}

{
  "steps": [
    {
      "id": "make_point",
      "operation": "run_sql",
      "arguments": {
        "query": "SELECT ST_Point(1, 1) AS geom",
        "output_path": "point.parquet"
      },
      "output": {"kind": "vector", "geometry": "point", "cardinality": "one"},
      "comment": "Create a point from the literal coordinate pair (1, 1); no prior dataset exists to read."
    },
    {
      "id": "point_as_text",
      "operation": "run_sql",
      "arguments": {
        "query": "SELECT ST_AsText(geom) AS wkt FROM read_parquet('$make_point')",
        "input_paths": ["$make_point"],
        "output_path": "point_wkt.parquet"
      },
      "output": {"kind": "table", "cardinality": "one"},
      "comment": "Read the point back as readable (WKT) text."
    },
    {
      "id": "buffer_area",
      "operation": "buffer_layer",
      "arguments": {
        "input_path": "$make_point",
        "distance_meters": 1,
        "output_path": "buffer_1unit.parquet"
      },
      "output": {"kind": "vector", "geometry": "polygon", "cardinality": "same_as_input"},
      "comment": "Area within 1 unit around the point, via metric buffer."
    }
  ],
  "assumptions": [
    "input_crs=undefined/planar (literal coordinates, no geographic CRS stated)",
    "distance_unit=1 coordinate unit (treated as buffer distance_meters=1 since CRS is not geographic)",
    "readable_text_format=WKT via ST_AsText"
  ],
  "warnings": [
    "No CRS was given for the point (1, 1); the buffer distance of 1 is applied as a literal planar unit rather than meters, since automatic UTM estimation only applies to geographic CRS inputs."
  ]
}
